package com.spendwise.transaction;import org.springframework.data.jpa.repository.JpaRepository;import java.time.LocalDate;import java.util.List;import java.util.Optional;
public interface TransactionRepository extends JpaRepository<Transaction,Long>{List<Transaction> findAllByUserEmailOrderByDateDesc(String userEmail);List<Transaction> findAllByUserEmailAndDateBetweenOrderByDateDesc(String userEmail,LocalDate start,LocalDate end);Optional<Transaction> findByIdAndUserEmail(Long id,String userEmail);}